<div class="gadsan-page-heading"><div><h2><i class="bi bi-search me-2" aria-hidden="true"></i>Conferir linha <?= (int)$origin['linha'] ?></h2><p><?= ge($origin['arquivo']) ?> · <?= ge($origin['aba']) ?></p></div><div class="gadsan-heading-actions"><a class="btn btn-light" href="/admin/gadsan/importacoes/<?= (int)$origin['importacao_id'] ?>"><i class="bi bi-arrow-left me-1"></i>Voltar à importação</a></div></div>
<?php if ($origin['colaborador_id']&&$canView): ?><div class="mb-4"><a class="btn btn-outline-primary" href="/admin/gadsan/colaboradores/<?= (int)$origin['colaborador_id'] ?>"><i class="bi bi-person-vcard me-1"></i>Abrir cadastro para conferência</a></div><?php endif ?>
<div class="row g-4 align-items-start"><div class="col-12 col-xl-5"><div class="card"><div class="card-header"><div class="gadsan-section-title"><span class="gadsan-section-icon"><i class="bi bi-file-earmark-text" aria-hidden="true"></i></span><div><h3>Valores originais</h3><p>Dados recebidos na planilha.</p></div></div></div><div class="card-body"><dl class="gadsan-original mb-0"><?php foreach (json_decode($origin['dados_originais'],true)??[] as $field=>$value): ?><dt><?= ge(str_replace('_',' ',$field)) ?></dt><dd><?= ge($value??'Não informado') ?></dd><?php endforeach ?></dl></div></div></div><div class="col-12 col-xl-7"><div class="d-flex align-items-start justify-content-between gap-3 mb-3"><div><h3 class="h5 mb-1">Inconsistências e revisão</h3><p class="text-muted small mb-0">Marque como resolvida após conferir e corrigir o cadastro.</p></div><span class="gadsan-badge <?= $issues?'gadsan-badge-warning':'gadsan-badge-success' ?>"><?= count($issues) ?> alerta(s)</span></div>
<?php foreach ($issues as $issue): ?><article class="card mb-3"><div class="card-body"><span class="gadsan-badge <?= $issue['resolvido']?'gadsan-badge-success':'gadsan-badge-warning' ?>"><i class="bi <?= $issue['resolvido']?'bi-check-circle':'bi-exclamation-circle' ?> me-1" aria-hidden="true"></i><?= $issue['resolvido']?'Resolvida':'Pendente' ?></span><h4 class="h6 mt-3 mb-2"><?= ge(str_replace('_',' ',$issue['tipo_inconsistencia'])) ?> <span class="text-muted">· <?= ge($issue['campo']) ?></span></h4><p class="mb-2"><?= ge($issue['descricao']) ?></p><p class="small text-muted mb-3"><strong>Valor recebido:</strong> <?= ge($issue['valor_original']??'Não informado') ?></p><form method="post" action="/admin/gadsan/inconsistencias/<?= (int)$issue['id'] ?>"><input type="hidden" name="_csrf" value="<?= ge($csrf) ?>"><input type="hidden" name="resolvido" value="<?= $issue['resolvido']?'0':'1' ?>"><button class="btn btn-sm btn-outline-primary"><?= $issue['resolvido']?'Reabrir pendência':'Marcar como resolvida' ?></button></form></div></article><?php endforeach ?>
<?php if (!$issues): ?><div class="gadsan-alert gadsan-alert-success"><i class="bi bi-check-circle-fill" aria-hidden="true"></i><span>Nenhuma inconsistência registrada nesta linha.</span></div><?php endif ?></div></div>
